function tr(zh,en){return lang==='zh'?zh:en}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function $(id){return document.getElementById(id)}function arr(v){return v||[]}function option(v,t,sel){return '<option value="'+esc(v)+'"'+(v===sel?' selected':'')+'>'+esc(t)+'</option>'}function button(a,label,cls,data){return '<button type="button" data-act="'+a+'" class="'+(cls||'')+'" '+(data||'')+'>'+label+'</button>'}function field(id,label,value,type,wide){return '<div class="field '+(wide?'wide':'')+'"><label for="'+id+'">'+esc(label)+'</label>'+(type==='textarea'?'<textarea id="'+id+'">'+esc(value)+'</textarea>':'<input id="'+id+'" type="'+(type||'text')+'" value="'+esc(value)+'">')+'</div>'}function value(id){return $(id)?$(id).value:''}function status(s){return '<span class="status '+esc(s)+'">'+esc(s)+'</span>'}function json(v){return JSON.stringify(v,null,2)}function selectedProject(){return arr(S.projects).find(function(p){return p.id===project})}function projectOptions(sel,empty){return (empty?option('',tr('全局 / 不关联项目','Global / no project'),sel):'')+arr(S.projects).map(function(p){return option(p.id,p.name,sel)}).join('')}
async function api(route,data){return new Promise(function(resolve,reject){var x=new XMLHttpRequest();x.open(data===undefined?'GET':'POST','/api/'+route);x.setRequestHeader('Authorization','Bearer '+token);if(data!==undefined)x.setRequestHeader('Content-Type','application/json');x.timeout=650000;x.onload=function(){if(x.status===401){var unauthorized=Error(tr('登录已失效，请在终端运行 ic-workbench --status 获取新链接；刷新页面可重新登录。','Login expired. Run ic-workbench --status for a fresh link, or reload to sign in.'));unauthorized.status=401;reject(unauthorized);return}var b;try{b=JSON.parse(x.responseText)}catch(e){reject(Error(tr('服务返回格式异常，请重新连接或检查服务日志。状态码：','Unexpected server response; reconnect or check service logs. Status: ')+x.status));return}if(x.status>=200&&x.status<300)resolve(b);else reject(Error(b.error||x.status))};x.onerror=function(){reject(Error(tr('连接失败，请检查服务','Connection failed')))};x.ontimeout=function(){reject(Error('Request timeout'))};x.send(data===undefined?null:JSON.stringify(data))})}
function act(action,input){return api('v2/action',{action:action,input:input||{}})}function toast(v){$('toast').textContent=v;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(function(){$('toast').style.display='none'},5500)}function notifyError(e){toast(e.message||e);var n=$('page-error');if(!n){n=document.createElement('div');n.id='page-error';n.className='notice error';n.setAttribute('role','alert');var host=$('modal')?$('modal').querySelector('.modal'):$('content');if(host)host.insertBefore(n,host.firstChild)}n.textContent=e.message||String(e)}
