function modal(title,body,save){var old=$('modal');if(old)old.remove();var el=document.createElement('div');el.id='modal';el.className='modal-backdrop';el.innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="row between"><h2>'+esc(title)+'</h2>'+button('close-modal','×','close')+'</div>'+body+'<div class="form-footer">'+button('close-modal',tr('取消','Cancel'))+(save?button(save,tr('保存','Save'),'primary'):'')+'</div></section>';document.body.appendChild(el);var first=el.querySelector('input,textarea');if(first)first.focus()}
