async function loadMessages(){if(!$('messages'))return;var s=session?await api('session?id='+encodeURIComponent(session)):null;if(!$('messages'))return;if(!run&&s&&s.lastTask)showAgentProgress(s.lastTask);if(!s||!arr(s.messages).length){$('messages').innerHTML='<div class="welcome"><div class="logo">⌁</div><h1>'+tr('从一个问题，开始今天的设计。','A clearer path from question to design.')+'</h1><p>'+tr('连接项目、工具与仿真结果，让 AI 参与每一步研发。','Bring projects, tools and simulation evidence into one conversation.')+'</p><div class="quick-actions">'+button('prompt-files','<b>▤ '+tr('整理项目','Explore a project')+'</b><small>'+tr('查看目录与文件说明','Browse files and annotations')+'</small>')+button('prompt-debug','<b>≋ '+tr('分析仿真','Analyze a simulation')+'</b><small>'+tr('从日志和波形寻找线索','Investigate logs and waveforms')+'</small>')+button('prompt-monitor','<b>⌁ '+tr('检查资源','Check resources')+'</b><small>'+tr('了解服务器和仿真任务','Inspect server and task usage')+'</small>')+'</div>'+(S.mode==='demo'?'<p class="footer-note">'+tr('当前为离线规则演示；真实问答与规划需连接公司内网 GLM。','Offline deterministic demo. Real answers and planning require your intranet GLM.')+'</p>':'')+'</div>'}else{$('messages').innerHTML=s.messages.map(function(m,i){return '<article class="message '+esc(m.role)+'">'+(m.role==='assistant'?'<div class="message-head">⌁ IC Agent</div>':'')+formatMessage(m.content)+(m.role==='assistant'?button('copy-message',tr('复制','Copy'),'link small','data-id="'+i+'"'):'')+(m.evidence?'<details><summary>'+tr('上下文证据','Context evidence')+'</summary><pre>'+esc(m.evidence)+'</pre></details>':'')+'</article>'}).join('');$('messages').scrollTop=$('messages').scrollHeight}}
async function sendChat(text,context){if(run){toast(tr('已有 Agent 正在执行','An Agent is already running'));return}text=text||value('chat-input');if(!text.trim())return;var linuxMode=value('linux-mode')||'off';var allow=$('allow-write')&&$('allow-write').checked;if(chatScope==='folder')chatFolder=value('chat-folder')||chatFolder;if(chatScope==='folder'&&!chatFolder)throw Error(tr('请输入文件夹路径','Enter a folder path'));if(chatScope==='project'&&!chatProject)throw Error(tr('请选择项目','Select a project'));if(!session){var s=await api('sessions',{title:text.slice(0,50),project:chatScope==='project'?chatProject:'',folder:chatScope==='folder'?chatFolder:''});session=s.id}var started=await api('v2/agent',{session:session,text:text,allowWrite:allow,context:context||'',linuxMode:linuxMode,maxRounds:(engineering.nextBudget||{}).maxRounds||12,maxSeconds:(engineering.nextBudget||{}).maxSeconds||600,readOnly:!!engineering.nextBudget,templateID:(engineering.nextBudget||{}).templateID||'',templateValues:(engineering.nextBudget||{}).templateValues||{}});engineering.nextBudget=null;run=started.id;if($('linux-mode'))$('linux-mode').value='off';syncScopeControls();sessionStorage.setItem('icw-run',run);chatText='';queueWorkspaceSave();if($('chat-input'))$('chat-input').value='';await refresh();await loadMessages();pollAgent()}
function linuxModeControls(){return '<div class="linux-controls"><label for="linux-mode">Linux Agent</label><select id="linux-mode"><option value="off">'+tr('关闭终端操作（默认）','Terminal off (default)')+'</option><option value="confirm">'+tr('本轮逐项确认','Confirm each action this turn')+'</option><option value="auto">'+tr('本轮自主执行','Autonomous execution this turn')+'</option></select><small>'+tr('自主模式允许 AI 以当前 Linux 账号执行命令和修改文件。目录只决定工作位置，并非沙箱；本轮结束授权即失效。','Autonomous mode lets AI run commands and edit files as your Linux account. The working directory is not a sandbox. Authorization expires after this turn.')+(S.mode==='demo'?' '+tr('Demo 仅模拟，不操作主机。','Demo simulates operations without touching the host.'):'')+'</small></div>'}
function showAgentProgress(r){if(!$('agent-progress'))return;var t=r.terminal;$('agent-progress').innerHTML='<div class="progress-panel"><div class="row between"><b>'+tr('执行进度','Execution progress')+'</b>'+status(r.status)+'</div>'+(r.directory?'<div class="footer-note">Linux '+esc(r.linuxMode)+' · '+esc(r.directory)+'</div>':'')+(r.pending?'<pre>'+esc(r.pending.action+'\n'+r.pending.input)+'</pre><div class="row">'+button('approve-agent',tr('确认执行该操作','Approve this action'),'primary small')+button('decline-agent',tr('拒绝','Decline'),'small')+'</div>':'')+(t?'<div class="linux-terminal"><div class="row between"><b>'+tr('终端执行回执','Terminal receipt')+(t.demo?' · DEMO':'')+'</b>'+status(t.status)+'</div><div class="footer-note">PID '+esc(t.pid)+' · '+tr('退出码','Exit code')+' '+esc(t.exitCode===null?'—':t.exitCode)+' · '+esc(t.directory)+'</div><pre class="command-line">$ '+esc(t.command)+'</pre><pre id="linux-output">'+esc(t.output)+'</pre>'+(t.truncated?'<small>'+tr('输出达到 64 KiB 上限，后续内容未保存。','Output reached the 64 KiB limit; subsequent content was not saved.')+'</small>':'')+'</div>':'')+'<details class="agent-trace"><summary>'+tr('工具执行轨迹','Tool execution trace')+'</summary>'+arr(r.events).slice(-8).map(function(e){return '<div class="event"><b>'+esc(e.stage)+'</b>'+(e.stage==='receipt'||e.stage==='tool'?'<details><summary>'+tr('查看工具记录','View tool record')+'</summary><pre>'+esc(e.text)+'</pre></details>':'<span>'+esc(e.text)+'</span>')+'</div>'}).join('')+'</details>'+(r.error?'<div class="error">'+esc(r.error)+'</div>':'')+'</div>'}
async function pollAgent(){clearTimeout(runTimer);if(!run||document.hidden)return;try{var r=await api('v2/progress?id='+encodeURIComponent(run));showAgentProgress(r);if(['completed','failed','cancelled','interrupted'].indexOf(r.status)>=0){run='';syncScopeControls();sessionStorage.removeItem('icw-run');await refresh();await loadMessages();return}}catch(e){notifyError(e);run='';syncScopeControls();sessionStorage.removeItem('icw-run');return}runTimer=setTimeout(pollAgent,1200)}
