async function renderProjectTab(){var p=selectedProject();if(!p||!$('project-body'))return;{var roots=[p.root].concat(arr(p.paths));if(roots.indexOf(root)<0)root=p.root;$('project-body').innerHTML='<div class="row between"><select id="root-select" aria-label="Project path">'+roots.map(function(r){return option(r,r,root)}).join('')+'</select>'+button('up-dir','↑ '+tr('上级目录','Parent'),'small')+'</div><div class="row"><input id="file-search" class="full" placeholder="'+tr('关键词搜索文件名与文本内容；留空项目可搜索全部已登记目录','Search filenames and text content across registered project paths')+'"></div><div class="row between"><span id="file-path" class="path">'+esc(path||'.')+'</span><div class="row"><label class="check"><input id="search-all" type="checkbox">'+tr('全部项目','All projects')+'</label>'+button('search-files',tr('搜索','Search'),'small')+button('browse-reset',tr('目录视图','Browse'),'small')+'</div></div><div id="file-results" class="card"></div>';await loadFiles()}}
function beginFileRequest(){var serial=++fileRequestSerial,target=$('file-results');return function(){return page==='projects'&&serial===fileRequestSerial&&target&&target===$('file-results')}}
async function loadFiles(){var current=beginFileRequest(),requestedPath=path;var b=await act('browse',{project:project,root:root,path:path,offset:offset});if(!current())return false;if(b.entries){$('file-results').innerHTML='<div class="tablewrap"><table><thead><tr><th>'+tr('名称','Name')+'</th><th>'+tr('备注 / 说明','Notes / description')+'</th><th></th></tr></thead><tbody>'+b.entries.map(function(f){return '<tr><td>'+button('open-file',(f.directory?'▱ ':'▧ ')+esc(f.name),'file-name','data-path="'+esc(f.path)+'" data-dir="'+f.directory+'"')+'</td><td>'+esc(f.notes||'—')+'<div class="sub">'+esc(f.description)+'</div></td><td>'+button('file-note',tr('备注','Annotate'),'link small','data-path="'+esc(f.path)+'"')+'</td></tr>'}).join('')+'</tbody></table></div>'+(b.entries.length?'':empty(tr('目录为空','Empty directory')))+'<div class="row between">'+(offset?button('files-prev',tr('上一页','Previous'),'small'):'<span></span>')+(b.more?button('files-next',tr('下一页','Next'),'small'):'')+'</div>'}else{modal(requestedPath,'<div class="notice">'+b.size+' bytes '+(b.truncated?tr('· 预览已截断','· Preview truncated'):'')+'</div><pre>'+esc(b.content)+'</pre><div class="row">'+button('analyze-current',tr('文件分析','Analyze'),'primary','data-path="'+esc(requestedPath)+'"')+button('file-note',tr('添加备注','Annotate'),'','data-path="'+esc(requestedPath)+'"')+'</div>')}return true}
function projectForm(edit){var p=edit?selectedProject():{};p=p||{};modal(edit?tr('编辑项目','Edit project'):tr('添加项目','Add project'),'<input id="edit-project-id" type="hidden" value="'+esc(p.id)+'"><div class="form-grid">'+field('project-name',tr('项目名称','Project name'),p.name)+field('project-tags',tr('标签（逗号分隔）','Tags (comma separated)'),arr(p.tags).join(', '))+field('project-root',tr('主目录（Linux 绝对路径）','Primary directory (absolute path)'),p.root,'text',true)+field('project-paths',tr('其他目录（每行一项）','Additional paths (one per line)'),arr(p.paths).join('\n'),'textarea',true)+field('project-description',tr('项目说明','Description'),p.description,'textarea',true)+field('project-notes',tr('备注','Notes'),p.notes,'textarea',true)+'</div>','save-project')}
function jobTable(jobs){return '<div class="tablewrap"><table><thead><tr><th>'+tr('任务','Task')+'</th><th>'+tr('时间','Created')+'</th><th>'+tr('状态','Status')+'</th><th></th></tr></thead><tbody>'+jobs.slice().reverse().map(function(j){return '<tr><td>'+esc(j.kind)+'<div class="path">'+j.id.slice(0,10)+'</div></td><td>'+esc(j.created)+'</td><td>'+status(j.status)+'</td><td>'+button('job-detail',tr('日志','Log'),'link','data-id="'+j.id+'"')+' '+button('job-cancel',tr('取消','Cancel'),'link','data-id="'+j.id+'"')+'</td></tr>'}).join('')+'</tbody></table></div>'}
function renderSoftware(){$('content').innerHTML=header(tr('软件管理','Software'),tr('统一启动语句，按版本切换环境。配置只加载到独立子进程。','One launch command per tool; isolated environments for each version.'),button('add-software','＋ '+tr('添加软件','Add software'),'primary'))+'<div class="grid">'+arr(S.software).map(function(s){return '<article class="card"><div class="row between"><div class="card-icon">▦</div>'+button('edit-software',tr('编辑','Edit'),'link small','data-id="'+s.id+'"')+'</div><h2>'+esc(s.name)+'</h2><p class="path">'+esc(s.command)+'</p><label>'+tr('版本环境','Version environment')+'</label><select id="version-'+s.id+'" class="full">'+arr(s.versions).map(function(v){return option(v.name,v.name,s.active)}).join('')+'</select><div class="form-footer">'+button('launch-software',tr('启动','Launch'),'primary small','data-id="'+s.id+'"')+'</div></article>'}).join('')+'</div>'+(arr(S.software).length?'':empty(tr('添加 Virtuoso、Spectre 或其他常用工具','Add Virtuoso, Spectre or your other tools')))+operationPanel('software')}
