function operationPanel(kind){var ops=arr(S.operations).filter(function(x){return !kind||x.kind===kind}).slice(-12).reverse();return '<div class="card"><div class="row between"><h3>'+tr('执行记录','Execution history')+'</h3>'+button('refresh-page',tr('刷新','Refresh'),'small')+'</div>'+ops.map(function(o){return '<div class="row between"><span>'+esc(o.name)+'</span><div class="row">'+status(o.status)+button('operation-log',tr('日志','Log'),'link small','data-id="'+o.id+'"')+(['queued','running'].indexOf(o.status)>=0?button('cancel-operation',tr('停止','Stop'),'link small','data-id="'+o.id+'"'):'')+'</div></div>'}).join('')+(ops.length?'':'<span class="muted">—</span>')+'</div>'}
