function pluginForm(){modal(tr('添加插件','Add plugin'),'<div class="row">'+button('bulk-plugins',tr('改用 JSON / 脚本批量导入','Use JSON / bulk import'),'small')+'</div><div class="form-grid">'+field('plugin-id',tr('唯一 ID','Unique ID'),'')+field('plugin-name',tr('插件名称','Plugin name'),'')+field('plugin-version',tr('版本','Version'),'1.0.0')+field('plugin-timeout',tr('超时 / 秒','Timeout / seconds'),30,'number')+field('plugin-exe',tr('程序 / 解释器绝对路径','Absolute program / interpreter path'),'','text',true)+field('plugin-args',tr('参数 JSON 数组','Argument JSON array'),'[]','text',true)+field('plugin-description',tr('功能说明','Description'),'','textarea',true)+'</div><p class="footer-note">'+tr('新增后默认禁用，审阅命令后再启用。','Disabled on import. Review the command before enabling.')+'</p>','install-single-plugin')}
function pluginGuide(){modal(tr('插件安装与开发','Plugin installation & development'),'<div class="notice">'+tr('插件以当前 Linux 用户权限运行。导入清单不执行代码；请先检查脚本来源与命令。','Plugins run with your Linux user permissions. Importing a manifest does not execute it; inspect the script and command first.')+'</div><p>'+tr('1. 将脚本放在自己的 Linux 目录。2. 填写 JSON 清单并导入。3. 启用后在默认工作目录运行。','1. Put the script in your Linux directory. 2. Import its JSON manifest. 3. Enable it and run it in the default workspace.')+'</p><pre>'+esc(json(pluginSample))+'</pre><p>'+tr('批量安装：清单中的 plugins 数组可包含多个插件。使用随包脚本：','Bulk install: put multiple manifests in the plugins array. Use the bundled script:')+'</p><pre>export ICW_TOKEN=...\npython /path/to/current-production/install_plugins.py --url http://127.0.0.1:8765 plugins.json</pre><p>'+tr('executable 必须为绝对路径。args 是参数数组，{project} 会替换为项目目录。标准输出和错误输出写入执行记录；运行有超时，可取消。更新同一 id 会替换配置，不删除历史。','executable must be absolute. args is an argument array; {project} expands to the project directory. Output is recorded; execution is timed and cancellable. Reimporting the same id updates configuration without deleting history.')+'</p>','')}
async function renderMonitor(){$('content').innerHTML=header(tr('资源监测','System monitor'),tr('观察当前服务器与仿真任务。页面可见时按配置间隔刷新。','Observe server and simulation processes. Refreshes at your configured interval while visible.'),'<input id="monitor-query" placeholder="'+tr('检索任务名称或 PID','Search task name or PID')+'" value="'+esc(monitorQuery)+'">'+button('monitor-settings',tr('提醒阈值','Alert threshold')))+'<div id="monitor-content">'+empty(tr('正在采样…','Sampling…'))+'</div>';await updateMonitor()}
async function updateMonitor(){if(page!=='monitor'||document.hidden)return;try{var m=await act('monitor');if(!$('monitor-content'))return;monitorHistory.push(m);if(monitorHistory.length>40)monitorHistory.shift();var metrics=[['CPU',m.cpu,'cpu'],[tr('内存','Memory'),m.memory,'memory'],[tr('存储','Storage'),m.storage,'storage'],['GPU',m.gpus.length?m.gpus[0].usage:null,'gpu']];$('monitor-content').innerHTML='<div class="row between"><p class="sub">'+esc(m.source)+' · '+esc(m.time)+'</p><span class="badge">'+tr('阈值','Threshold')+' '+(S.preferences.threshold||90)+'%</span></div><div class="grid four">'+metrics.map(function(x){return '<div class="card"><span class="muted">'+x[0]+'</span><div class="metric">'+(x[1]==null?'—':x[1].toFixed(1)+'<small>%</small>')+'</div><div class="meter"><progress max="100" value="'+(x[1]||0)+'"></progress></div><canvas class="spark" data-metric="'+x[2]+'" width="300" height="56"></canvas></div>'}).join('')+'</div>'+m.alerts.map(function(a){return '<div class="notice warning" role="alert">'+esc(a)+'</div>'}).join('')+m.notes.map(function(n){return '<p class="footer-note">'+esc(n)+'</p>'}).join('')+'<p class="path">'+tr('存储所在文件系统：','Storage filesystem: ')+esc(m.storagePath)+'</p>'+(m.gpus.length?'<div class="card"><h3>GPU</h3><table><thead><tr><th>'+tr('设备','Device')+'</th><th>'+tr('计算占用','Utilization')+'</th><th>'+tr('显存占用','Memory used')+'</th></tr></thead><tbody>'+m.gpus.map(function(g){return '<tr><td>'+esc(g.name)+'</td><td>'+g.usage.toFixed(1)+'%</td><td>'+g.memory.toFixed(1)+'%</td></tr>'}).join('')+'</tbody></table></div>':'')+'<div class="card"><div class="row between"><h2>'+tr('资源占用最多的任务','Top resource consumers')+'</h2><label class="check"><input id="sim-only" type="checkbox" '+(monitorSimOnly?'checked':'')+'>'+tr('只看仿真任务','Simulation tasks only')+'</label></div><p class="sub">'+tr('按区间 CPU 占用排序；相同时按内存排序。CPU 100% 为一个逻辑核心。','Sorted by interval CPU usage, then memory. CPU 100% is one logical core.')+'</p><div class="tablewrap"><table><thead><tr><th>PID / '+tr('任务','Task')+'</th><th>CPU</th><th>'+tr('内存','Memory')+'</th><th>'+tr('权限','Owner')+'</th><th></th></tr></thead><tbody>'+m.processes.filter(function(p){return (!monitorSimOnly||p.simulation)&&(!monitorQuery||(p.name+' '+p.pid).toLowerCase().indexOf(monitorQuery.toLowerCase())>=0)}).map(function(p){return '<tr data-simulation="'+p.simulation+'"><td>'+p.pid+' · '+esc(p.name)+(p.simulation?' <span class="tag">EDA</span>':'')+'</td><td>'+p.cpu.toFixed(1)+'%</td><td>'+(p.memoryBytes/1048576).toFixed(1)+' MiB</td><td>'+tr(p.own?'本人':'其他用户',p.own?'Me':'Other user')+'</td><td>'+(p.own?button('terminate-process',tr('关闭任务','Terminate'),'danger small','data-id="'+p.pid+'" data-start="'+esc(p.start)+'" data-name="'+esc(p.name)+'"'):'—')+'</td></tr>'}).join('')+'</tbody></table></div></div>';document.querySelectorAll('.spark').forEach(function(c){drawSpark(c)});if(m.alerts.length)toast(m.alerts.join(' · '))}catch(e){notifyError(e)}monitorTimer=setTimeout(updateMonitor,(S.preferences.pollSeconds||5)*1000)}
function drawSpark(c){var ctx=c.getContext('2d'),key=c.dataset.metric;ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#709479';ctx.lineWidth=1.5;ctx.beginPath();monitorHistory.forEach(function(m,i){var v=key==='gpu'?(m.gpus[0]||{}).usage:m[key];if(v==null)return;var x=i/(Math.max(12,monitorHistory.length)-1)*c.width,y=c.height-5-v/100*45;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke()}
function renderAnalysis(){$('content').innerHTML=header(tr('文件分析','File analysis'),tr('浏览 Virtuoso / Spectre、DC、Calibre、VCS 报告，以及 CSV / VCD 波形。','Browse Virtuoso / Spectre, DC, Calibre and VCS outputs; inspect CSV / VCD waveforms.'),button('sample-wave',tr('示例波形','Sample waveform')))+'<div class="row"><input type="file" id="analysis-file" aria-label="Import report or waveform"><span class="sub">'+tr('文本 / 报告 / 网表 / CSV / VCD · 每次最多 2 MiB','Text / reports / netlists / CSV / VCD · 2 MiB per import')+'</span></div><div class="notice">'+tr('PSF、FSDB、WLF 等专有二进制格式请先通过厂商工具导出 CSV/VCD；这里不会将未解析数据当作波形。','Export proprietary PSF, FSDB and WLF data to CSV/VCD using vendor tools before importing.')+'</div>'+engineeringEntry('metric-dialog',tr('指标比较 · 单位与工况','Metrics · units & conditions'),tr('导入基线与候选 CSV，先核对 PVT 再比较','Import baseline and candidate CSV; check PVT first'))+'<div id="analysis-body"></div>';showAnalysis()}
function showAnalysis(){if(!$('analysis-body'))return;captureAnalysis();showAnalysisHistory();if(!analysis){$('analysis-body').innerHTML='<div class="big-drop">≋<h2>'+tr('把报告和波形放到同一个视野','Reports and waveforms, in one place')+'</h2><p>'+tr('选择本地文件导入，或从项目目录中打开文件。','Import a local file, or open one from a project directory.')+'</p></div>';return}var a=analysis;$('analysis-body').innerHTML='<div class="row between"><h2>'+esc(a.name)+'</h2><div class="row"><span class="badge">'+esc(a.format)+'</span>'+button('analyze-ai',tr('让 AI 分析','Analyze with AI'),'primary small')+'</div></div>'+(a.limited?'<div class="notice warning">'+tr('达到预览上限，数据不完整。请导出更小时间窗口。','Preview limit reached; data is incomplete. Export a smaller time window.')+'</div>':'')+(a.signals.length?'<div class="card"><div class="row"><label>'+tr('信号','Signal')+'</label><select id="wave-signal">'+a.signals.map(function(s,i){return option(String(i),s.name,String(0))}).join('')+'</select><span class="tag">'+esc(a.timescale)+'</span></div><canvas id="wave-canvas" class="wave" width="1200" height="340"></canvas><div class="wave-tools">'+button('zoom-in','＋','small')+button('zoom-out','−','small')+button('zoom-reset',tr('复位','Reset'),'small')+'<input type="range" id="wave-pan" min="0" max="1000" value="0" aria-label="Pan waveform"><span id="wave-range" class="path"></span></div></div>':'')+'<details open><summary>'+tr('文件内容','File contents')+'</summary><pre>'+esc(a.text)+'</pre></details><details><summary>'+tr('规则诊断（非 AI 结论）','Rule-based diagnostics (not an AI conclusion)')+'</summary><pre>'+esc(json(a.diagnostics))+'</pre></details>'+analysisAISection();drawWave()}
function drawWave(){var c=$('wave-canvas');if(!c||!analysis)return;var signal=analysis.signals[Number(value('wave-signal')||0)],pts=signal.points;if(!pts.length)return;var ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);var minT=pts[0].t,maxT=pts[pts.length-1].t,span=(maxT-minT||1)/waveZoom,start=minT+(maxT-minT-span)*wavePan;var values=pts.filter(function(p){return p.t>=start&&p.t<=start+span&&p.v!=null}).map(function(p){return p.v});if(!values.length)values=[0,1];var lo=Infinity,hi=-Infinity;values.forEach(function(v){lo=Math.min(lo,v);hi=Math.max(hi,v)});if(lo===hi){lo-=.5;hi+=.5}var pad=(hi-lo)*.12;lo-=pad;hi+=pad;function x(t){return 65+(t-start)/span*(w-90)}function y(v){return h-38-(v-lo)/(hi-lo)*(h-62)}ctx.font='12px monospace';ctx.strokeStyle='#e0e7db';ctx.fillStyle='#7c8c80';for(var i=0;i<=5;i++){var yy=24+i*(h-62)/5;ctx.beginPath();ctx.moveTo(65,yy);ctx.lineTo(w-25,yy);ctx.stroke();ctx.fillText((hi-i*(hi-lo)/5).toPrecision(3),4,yy+4)}for(i=0;i<=5;i++){var xx=65+i*(w-90)/5;ctx.beginPath();ctx.moveTo(xx,24);ctx.lineTo(xx,h-38);ctx.stroke();ctx.fillText((start+i*span/5).toPrecision(4),xx-20,h-15)}ctx.save();ctx.beginPath();ctx.rect(65,24,w-90,h-62);ctx.clip();ctx.strokeStyle='#376657';ctx.lineWidth=2;ctx.beginPath();var prev=null;pts.forEach(function(p){if(p.v==null){prev=null;return}if(!prev)ctx.moveTo(x(p.t),y(p.v));else{if(signal.digital)ctx.lineTo(x(p.t),y(prev.v));ctx.lineTo(x(p.t),y(p.v))}prev=p});ctx.stroke();ctx.restore();$('wave-range').textContent='×'+waveZoom.toFixed(1)+' · '+start.toPrecision(4)+' — '+(start+span).toPrecision(4);c.onwheel=function(e){e.preventDefault();waveZoom=Math.max(1,Math.min(128,waveZoom*(e.deltaY<0?1.25:.8)));drawWave()}}
function hdlExt(){return (arr(meta.codeLanguages).find(function(x){return x.id===hdlLang})||{}).extension||'.txt'}
async function renderSettings(){var res=await act('preferences');if(page!=='settings')return;var p=res.preferences;$('content').innerHTML=header(tr('设置与验证','Settings & validation'),tr('配置持久保存，启动与保存后自动加载，并检查实际状态。','Persistent configuration loads and validates on startup and after saving.'),button('validate-settings',tr('重新验证','Validate now')))+'<div class="grid two"><section class="card"><h2>'+tr('AI 模型','AI model')+'</h2><p>'+tr('公司内网 GLM · OpenAI 兼容 Chat Completions 接口','Intranet GLM · OpenAI-compatible Chat Completions endpoint')+'</p><div class="form-grid">'+field('settings-model-url',tr('完整接口地址','Full endpoint URL'),p.modelUrl,'url',true)+field('settings-model',tr('模型标识','Model identifier'),p.model)+field('settings-key-env',tr('密钥环境变量名','API key environment variable'),p.keyEnv)+'<label class="check wide"><input id="settings-tools" type="checkbox" '+(p.modelTools?'checked':'')+'>'+tr('启用模型工具调用（Agent）','Enable model tool calling (Agent)')+'</label></div><p class="footer-note">'+tr('密钥由启动进程的环境变量提供，不存入网页。Demo 不连接真实模型。','Provide the key via the launch process environment. Demo never connects to a real model.')+'</p></section><section class="card"><h2>'+tr('Linux 工作环境','Linux environment')+'</h2><p>'+tr('加载到子进程，不修改用户全局 shell 文件。','Loaded in child processes; global shell configuration is preserved.')+'</p><div class="form-grid">'+field('settings-shell','Shell',p.shell)+field('settings-workspace',tr('默认工作目录','Default workspace'),p.workspace)+field('settings-setup',tr('环境加载脚本（可空）','Environment setup script (optional)'),p.setup,'text',true)+field('settings-threshold',tr('资源提醒阈值 %','Resource alert threshold %'),p.threshold,'number')+field('settings-poll',tr('刷新间隔（3–60 秒）','Refresh interval (3–60 seconds)'),p.pollSeconds,'number')+'</div></section></div><div class="card"><h2>'+tr('原有 HDL 检查工具（兼容配置）','Legacy HDL checker')+'</h2><div class="form-grid">'+field('settings-compiler',tr('可执行文件绝对路径','Absolute executable path'),p.compiler.executable)+field('settings-compiler-args',tr('参数 JSON（使用 {file}）','Arguments JSON (use {file})'),json(p.compiler.args||[]))+'</div><p class="footer-note">'+tr('示例：/usr/bin/iverilog，参数 ["-g2012","-tnull","{file}"]。VHDL 可配置 ghdl -s。','Example: /usr/bin/iverilog with ["-g2012","-tnull","{file}"]. For VHDL configure ghdl -s.')+'</p></div><div class="row between"><p class="sub">'+tr('工程数据由公司备份，平台保留路径、配置和个人工作记录。','Company backup covers project data; the platform retains paths, settings and personal work records.')+'</p>'+button('save-settings',tr('保存并加载','Save & load'),'primary')+'</div><div id="validation-state"></div>';showValidation(res.validation);pollValidation();await showStorageUsage()}
function showValidation(v){if(!$('validation-state'))return;$('validation-state').innerHTML='<div class="card"><div class="row between"><h2>'+tr('验证状态','Validation status')+'</h2><span class="path">'+esc(v.time)+'</span></div><div class="row"><b>AI</b>'+status(v.model)+'<b>Linux</b>'+status(v.environment)+'</div>'+arr(v.details).map(function(d){return '<div class="notice warning">'+esc(d)+'</div>'}).join('')+'</div>'}
async function pollValidation(){if(page!=='settings'||document.hidden)return;var v=await act('preferences');showValidation(v.validation);if(v.validation.model==='checking'||v.validation.environment==='checking')setTimeout(function(){pollValidation().catch(notifyError)},1200)}
async function importAnalysis(file){if(file.size>2*1024*1024)throw Error(tr('文件超过 2 MiB，请先导出选定窗口','File exceeds 2 MiB; export a selected window first'));var text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(await readFileBuffer(file))}catch(e){throw Error(tr('文件不是 UTF-8 文本，请按原编码转换后导入','File is not UTF-8; convert using its original encoding first'))}captureAnalysis();analysisID='';analysis=await act('analysis',{name:file.name,content:text});waveZoom=1;wavePan=0;showAnalysis();queueWorkspaceSave()}
function syncScopeControls(){['chat-scope','chat-project','chat-folder','session-select','linux-mode','allow-write'].forEach(function(id){if($(id))$(id).disabled=!!run})}
function chatScopeControls(){return '<div class="chat-scope row"><label>'+tr('操作范围','Working scope')+'</label><select id="chat-scope">'+option('none',tr('通用问答','General questions'),chatScope)+option('project',tr('项目','Project'),chatScope)+option('folder',tr('文件夹','Folder'),chatScope)+'</select>'+(chatScope==='project'?'<select id="chat-project" aria-label="Chat project">'+projectOptions(chatProject,true)+'</select>':chatScope==='folder'?'<input id="chat-folder" aria-label="Chat folder" placeholder="/home/user/design" value="'+esc(chatFolder)+'">':'')+'<span class="sub">'+tr('切换范围将开启新对话','Changing scope starts a new conversation')+'</span></div>'}
function adoptSessionScope(){var s=arr(S.sessions).find(function(s){return s.id===session});if(s){chatProject=s.project||'';chatFolder=s.folder||'';chatScope=chatFolder?'folder':chatProject?'project':'none'}}
function renderCalculator(){
 $('content').innerHTML=header(tr('计算器','Calculator'),tr('从一个算式到一组设计变量。支持科学函数和工程计数法。','From a single expression to design variables, scientific functions and engineering notation.'))+
 '<div class="calc-presets row">'+button('calc-preset',tr('RC 截止频率','RC cutoff'),'small','data-id="rc"')+button('calc-preset',tr('热噪声','Thermal noise'),'small','data-id="noise"')+button('calc-preset',tr('增益 dB','Gain in dB'),'small','data-id="gain"')+button('calc-preset',tr('普通计算','Arithmetic'),'small','data-id="basic"')+'</div><div class="grid two"><section class="card"><h2>'+tr('公式与变量','Formula & variables')+'</h2><label for="calc-expression">'+tr('计算公式','Expression')+'</label><input id="calc-expression" class="full code-input" value="'+esc(calc.expression)+'" placeholder="1/(2*pi*R*C)"><label for="calc-variables">'+tr('变量（每行 name = 数值或公式）','Variables (one name = value or expression per line)')+'</label><textarea id="calc-variables" class="full code-input calc-vars">'+esc(calc.variables)+'</textarea><div class="row between"><select id="calc-angle">'+option('rad',tr('弧度 rad','Radians'),calc.angle)+option('deg',tr('角度 deg','Degrees'),calc.angle)+'</select>'+button('calculate',tr('计算','Calculate'),'primary')+'</div><div id="calc-error" role="alert"></div></section><section class="card soft"><span class="muted">'+tr('计算结果','Result')+'</span><div id="calc-result">'+calculatorResult()+'</div></section></div><div class="card"><h3>'+tr('语法速查','Quick reference')+'</h3><p>+ − * / % ^ · sqrt, abs, exp, ln/log, log10, log2, sin/cos/tan, asin/acos/atan, atan2, pow, min/max, floor/ceil/round</p><p>'+tr('常量：pi、e、kB（玻尔兹曼常量）、qe（元电荷）。使用 * 表示乘法。','Constants: pi, e, kB (Boltzmann constant), qe (elementary charge). Use * for multiplication.')+'</p><p>'+tr('数值后缀：f p n u m k M meg G T。m = 10⁻³，M/meg = 10⁶；1e-9 也有效。log 为自然对数，% 为取余。计算使用双精度数值，不执行代码、不自动换算单位。','Suffixes: f p n u m k M meg G T. m = 10⁻³, M/meg = 10⁶; 1e-9 also works. log is natural log; % is modulo. Double-precision numeric evaluation; no code execution or automatic unit conversion.')+'</p></div>';
}
function calculatorResult(){return calc.result?'<div class="calc-number">'+esc(calc.result.formatted)+'</div><p class="path">'+esc(calc.result.expression)+'</p><table><tbody>'+Object.keys(calc.result.variables).map(function(k){return '<tr><td>'+esc(k)+'</td><td>'+esc(calc.result.variables[k])+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">'+tr('输入公式，开始计算','Enter an expression to calculate')+'</div>'}
function analysisAISection(){return '<section class="card analysis-answer"><div class="row between"><h2>'+tr('AI 分析结果','AI analysis')+'</h2>'+button('copy-analysis',tr('复制结果','Copy result'),'small')+'</div><label for="analysis-question">'+tr('分析重点（可选）','Analysis focus (optional)')+'</label><textarea id="analysis-question" class="full" placeholder="'+tr('例如：定位收敛错误，说明证据和建议的排查步骤','Example: locate convergence issues with evidence and suggested checks')+'">'+esc(analysis.question||'')+'</textarea><div class="form-footer">'+button('analyze-ai',analysis.busy?tr('正在分析…','Analyzing…'):tr('分析当前文件','Analyze this file'),'primary')+'</div><div id="analysis-ai-result" aria-live="polite">'+(analysis.busy?'<div class="notice">'+tr('正在读取文件并分析，结果会显示在这里。','Reading and analyzing this file. Results will appear here.')+'</div>':analysis.error?'<div class="notice error">'+esc(analysis.error)+'</div>':analysis.answer?formatMessage(analysis.answer):'<p class="sub">'+tr('分析结果会保留在当前文件页面。','Results stay on this file page.')+'</p>')+'</div></section>'}
function renderCode(){
 var languages=arr(meta.codeLanguages),draft=currentCodeDraft();$('content').innerHTML=header(tr('Code 平台','Code platform'),tr('生成、编辑和导出电路设计代码。为每种语言单独配置检查工具。','Generate, edit and export circuit design code. Configure a checker for each language.'),'<select id="hdl-language" aria-label="Code language">'+languages.map(function(x){return option(x.id,x.name+' · '+x.extension,hdlLang)}).join('')+'</select>'+button('code-checker',tr('检查工具','Checker settings')))+
 engineeringEntry('changes-dialog',tr('AI 多文件修改集','AI multi-file changes'),tr('协同修改 RTL、脚本与约束；逐文件审阅、采用和撤销','Coordinate RTL, scripts and constraints; review, apply and undo each file'))+codeImportBar()+'<div class="hdl-grid"><section><div class="editor"><div class="editor-head"><b>'+tr('需求与约束','Requirements & constraints')+'</b><span>INPUT</span></div><textarea id="hdl-requirements" placeholder="'+tr('描述电路、接口、工艺假设、仿真条件和预期输出。例如：编写 Verilog-A 运放模型，限制增益带宽和输出摆幅。','Describe the circuit, interfaces, process assumptions and expected outputs. Example: a Verilog-A amplifier with limited gain bandwidth and output swing.')+'">'+esc(hdlReq)+'</textarea></div><div class="form-footer">'+button('improve-code',codeBusy?tr('正在生成修改建议…','Preparing changes…'):tr('AI 优化当前代码','Improve current code'),'primary')+button('generate-hdl',tr('生成新代码','Generate new code'))+'</div>'+codeOriginalSection(draft)+'</section><section><div class="editor"><div class="editor-head"><b>'+tr('代码 · 可编辑','Code · editable')+'</b><span id="hdl-filename">design'+hdlExt()+'</span></div><textarea id="hdl-code" class="code-input" spellcheck="false">'+esc(hdlCode)+'</textarea></div><div class="form-footer">'+button('compile-hdl',tr('检查 / 编译','Check / compile'))+button('repair-code',tr('检查并 AI 修复','Check & AI repair'))+button('format-code',tr('预览整份排版','Preview file layout'))+button('format-selection',tr('预览选中行排版','Preview selected lines'))+button('save-hdl',tr('另存为','Save as'))+button('export-hdl',tr('导出文件','Export'),'primary')+'</div></section></div><div class="notice">'+tr('Demo 提供各语言固定示例；正式模式使用内网 AI。生成结果需通过对应工具验证，切换语言会保留各自草稿。','Demo provides fixed examples per language. Production uses intranet AI. Validate generated code with the matching tool; each language keeps its own draft.')+'</div>'+'<div class="notice">'+tr('排版仅调整缩进与空白，不修复逻辑。先在代码框选中内容，再点“预览选中行排版”；整份排版忽略选区。结果在下方比较，点击采用后才替换草稿。','Formatting adjusts layout, not logic. Select source text before previewing selected lines; file layout ignores selection. Review the result below before applying.')+'</div><div id="code-diagnostics"></div>'+codeReviewSection(draft)+operationPanel('compile');pollCodeTask();
}
function edaConnections(){return [{id:'builtin',name:'Virtuoso / Spectre',transport:'builtin'}].concat(arr(S.mcpConnections))}
function renderEDA(){
 var connections=edaConnections(),c=connections.find(function(x){return x.id===edaID})||connections[0];edaID=c.id;
 $('content').innerHTML=header(tr('EDA 控制','EDA control'),tr('通过 MCP 连接工具、提交仿真并读取执行结果。','Connect tools, submit simulations and inspect results through MCP.'),button('eda-guide',tr('接入说明','Connection guide'))+button('add-mcp','＋ '+tr('添加 MCP','Add MCP'),'primary'))+
 '<div class="split"><aside class="list-panel">'+connections.map(function(x){return button('select-mcp',esc(x.name)+'<small>'+esc(x.transport==='builtin'?tr('内置 Cadence 桥接','Built-in Cadence bridge'):x.transport)+'</small>','list-item '+(x.id===edaID?'selected':''),'data-id="'+esc(x.id)+'"')}).join('')+'</aside><section><div class="row between"><div><h2>'+esc(c.name)+'</h2><span class="badge">MCP · '+esc(c.transport)+'</span></div><div class="row">'+(c.id!=='builtin'?button('edit-mcp',tr('编辑连接','Edit connection'),'small','data-id="'+esc(c.id)+'"'):'')+button('disconnect-mcp',tr('断开','Disconnect'),'small')+button('discover-mcp',tr('连接并获取工具','Connect & discover'),'primary small')+'</div></div>'+(S.mode==='demo'?'<div class="notice">'+tr('Demo 通过真实 MCP 协议连接本地模拟桥接；外部服务与 EDA 不会执行。','Demo uses the real MCP protocol with a local simulated bridge. External servers and EDA are not executed.')+'</div>':'')+(c.id==='builtin'?'<p class="sub">'+tr('使用已配置的 Virtuoso/OCEAN/Spectre 适配器；先验证连接，再提交仿真。','Uses your configured Virtuoso/OCEAN/Spectre adapter. Probe before submitting simulations.')+'</p>'+button('cadence-config',tr('Cadence 工程接入配置','Cadence project configuration'),'link small'):'')+'<div id="eda-agent"></div><details class="card"><summary>'+tr('手动 MCP 工具调用','Manual MCP tools')+'</summary><div id="eda-tools"></div></details></section></div><div id="eda-history">'+operationPanel('mcp')+'</div><details><summary>'+tr('仿真任务状态与日志','Simulation job status & logs')+'</summary><div id="eda-jobs">'+jobTable(arr(S.jobs))+'</div></details>';showEDATools();renderEDAAgent();
}
function showEDATools(){if(!$('eda-tools'))return;var state=edaCatalog[edaID];if(!state){$('eda-tools').innerHTML=empty(tr('连接后查看该服务实际提供的工具。','Connect to discover the tools provided by this server.'));return}var tools=arr(state.tools),t=tools.find(function(x){return x.name===edaTool})||tools[0];if(!t){$('eda-tools').innerHTML=empty(tr('该 MCP 服务未提供工具','No tools were advertised by this MCP server'));return}edaTool=t.name;var defaults={};if(t.name==='probe_virtuoso'||t.name==='submit_simulation')defaults={project:arr(S.projects)[0]?S.projects[0].id:'',params:{}};if(t.name==='job_status'||t.name==='cancel_job')defaults={job:arr(S.jobs).length?S.jobs[S.jobs.length-1].id:''};
 $('eda-tools').innerHTML='<div class="card soft"><label>'+tr('工具','Tool')+'</label><select id="eda-tool" class="full">'+tools.map(function(x){return option(x.name,x.name,edaTool)}).join('')+'</select><p class="sub">'+esc(t.description||'')+'</p><details><summary>'+tr('参数格式','Parameter schema')+'</summary><pre>'+esc(json(t.inputSchema))+'</pre></details><label for="eda-args">'+tr('调用参数 JSON','Tool arguments JSON')+'</label><textarea id="eda-args" class="full code-input">'+esc(json(defaults))+'</textarea><div class="form-footer">'+button('call-mcp',tr('调用工具','Call tool'),'primary')+'</div></div>';
}
function mcpForm(id){var c=arr(S.mcpConnections).find(function(x){return x.id===id})||{transport:'stdio',command:{args:[]},timeoutSeconds:60,allowedTools:[]};modal(tr('MCP 连接配置','MCP connection'),'<input id="mcp-id" type="hidden" value="'+esc(c.id||'')+'"><div class="form-grid">'+field('mcp-name',tr('名称 / EDA 软件','Name / EDA software'),c.name)+'<div class="field"><label>'+tr('连接方式','Transport')+'</label><select id="mcp-transport">'+option('stdio','stdio',c.transport)+option('http','Streamable HTTP',c.transport)+'</select></div>'+field('mcp-exe',tr('stdio 可执行文件绝对路径','stdio absolute executable'),c.command.executable)+field('mcp-args',tr('stdio 参数 JSON 数组','stdio arguments JSON array'),json(c.command.args||[]))+field('mcp-directory',tr('stdio 工作目录','stdio working directory'),c.directory,'text',true)+field('mcp-url',tr('HTTP MCP 地址','HTTP MCP endpoint'),c.url,'text',true)+field('mcp-token-env',tr('HTTP 凭据环境变量名（可空）','HTTP token environment variable (optional)'),c.tokenEnv)+field('mcp-timeout',tr('调用超时 / 秒','Call timeout / seconds'),c.timeoutSeconds,'number')+field('mcp-allowed',tr('允许调用的工具（每行一个名称）','Allowed tool names (one per line)'),arr(c.allowedTools).join('\n'),'textarea',true)+'</div><p class="footer-note">'+tr('保存不启动程序。点击连接会启动 stdio 服务或访问 HTTP 地址；请使用已安装、已审阅的本地服务。工具白名单可在首次发现工具后填写。','Saving does not start a process. Connect starts the stdio server or contacts the HTTP endpoint. Use an installed, reviewed server; fill the allowlist after discovering tools.')+'</p>','save-mcp')}
function edaGuide(){modal(tr('EDA / MCP 接入说明','EDA / MCP connection guide'),'<ol><li>'+tr('内置 Cadence：在工程接入配置中填写适配器 JSON 与环境。连接后调用 probe_virtuoso，再调用 submit_simulation，使用 job_status 跟踪实际任务。','Built-in Cadence: configure the adapter JSON and environment, call probe_virtuoso, then submit_simulation; poll job_status for the actual job.')+'</li><li>'+tr('其他软件：先部署对应 MCP 服务，再添加其 stdio 命令或 Streamable HTTP 地址。发现工具后，把需要调用的工具名加入白名单。','Other software: deploy an MCP server, then add its stdio command or Streamable HTTP endpoint. Discover tools and add allowed names before calling.')+'</li><li>'+tr('参数遵循服务返回的 schema。调用记录是 MCP 回执；异步 EDA 任务还需继续查询完成状态。断开只关闭 MCP 会话，不保证撤销已提交到远端的任务。','Arguments follow the advertised schema. MCP receipts are not EDA completion; poll asynchronous tasks. Disconnect closes the MCP session and does not guarantee cancellation of remote work.')+'</li></ol><p>'+tr('参考：官方 MCP Go SDK、SkillBridge、OpenROAD-MCP。商业 EDA 需要公司安装、许可证与版本适配；桥接运行时可部署在支持的内网机器上。','References: official MCP Go SDK, SkillBridge and OpenROAD-MCP. Commercial tools need company installations, licenses and version-specific adapters; bridge runtimes may run on a supported intranet host.')+'</p><p class="path">docs/EDA_MCP.md · docs/EDA_ADAPTER.md</p>','')}
async function newActions(a,el){switch(a){
case 'login':var entered=value('login-token').trim();if(!entered)return true;sessionStorage.setItem('icw-token',entered);sessionStorage.removeItem('icw-run');location.reload();return true;
 case 'calculate':calc.expression=value('calc-expression');calc.variables=value('calc-variables');calc.angle=value('calc-angle');try{calc.result=await act('calculate',calcInput());$('calc-error').textContent='';$('calc-result').innerHTML=calculatorResult()}catch(e){calc.result=null;$('calc-result').innerHTML=calculatorResult();$('calc-error').innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}break;
 case 'calc-preset':var presets={rc:{expression:'1/(2*pi*R*C)',variables:'R = 1k\nC = 1n'},noise:{expression:'sqrt(4*kB*T*R*BW)',variables:'T = 300\nR = 10k\nBW = 20k'},gain:{expression:'20*log10(Vout/Vin)',variables:'Vin = 10m\nVout = 1'},basic:{expression:'(12+8)*3/2',variables:''}};Object.assign(calc,presets[el.dataset.id],{result:null});renderCalculator();break;
 case 'copy-analysis':if(analysis&&analysis.answer){await copyText(analysis.answer);toast(tr('已复制','Copied'))}break;
 case 'legacy-code-checker':var p=(await act('preferences')).preferences,c=(p.compilers||{})[hdlLang]||{};modal(tr('配置当前语言的检查工具','Configure checker for this language'),'<h3>'+esc(hdlLang)+'</h3><p class="sub">'+tr('请选择语法检查或编译命令；脚本语言不默认运行生成代码。','Choose a syntax-check or compile command. Generated scripts are not run by default.')+'</p><div class="form-grid">'+field('code-check-exe',tr('可执行文件绝对路径','Absolute executable'),c.executable,'text',true)+field('code-check-args',tr('参数 JSON（使用 {file}）','Arguments JSON (use {file})'),json(c.args||[]),'text',true)+'</div><p class="path">Python: ["-m", "py_compile", "{file}"] · Bash: ["-n", "{file}"]</p>','save-code-checker');break;
 case 'legacy-save-code-checker':var p=(await act('preferences')).preferences;p.compilers=p.compilers||{};p.compilers[hdlLang]={executable:value('code-check-exe'),args:JSON.parse(value('code-check-args'))};await act('save-preferences',p);closeModal();await refresh();toast(tr('检查工具已保存','Checker saved'));break;
 case 'legacy-confirm-compile':await act('compile-code',{language:hdlLang,code:hdlCode});closeModal();await refresh();renderCode();break;
 case 'select-mcp':edaID=el.dataset.id;edaTool='';renderEDA();break;
 case 'add-mcp':mcpForm('');break;case 'edit-mcp':mcpForm(el.dataset.id);break;
 case 'save-mcp':var c=await act('save-mcp',{id:value('mcp-id'),name:value('mcp-name'),transport:value('mcp-transport'),command:{executable:value('mcp-exe'),args:JSON.parse(value('mcp-args'))},directory:value('mcp-directory'),url:value('mcp-url'),tokenEnv:value('mcp-token-env'),timeoutSeconds:Number(value('mcp-timeout')),allowedTools:value('mcp-allowed').split('\n').map(function(x){return x.trim()}).filter(Boolean)});edaID=c.id;delete edaCatalog[c.id];closeModal();await refresh();renderEDA();break;
 case 'discover-mcp':var target=edaID;toast(tr('正在连接并获取工具…','Connecting and discovering tools…'));var list=await act('mcp-tools',{id:target});edaCatalog[target]=list;if(page==='eda'&&edaID===target)showEDATools();toast(tr('MCP 已连接','MCP connected'));break;
 case 'disconnect-mcp':await act('disconnect-mcp',{id:edaID});delete edaCatalog[edaID];showEDATools();toast(tr('已断开 MCP 会话','MCP session disconnected'));break;
 case 'call-mcp':var args=JSON.parse(value('eda-args'));if(!args||Array.isArray(args)||typeof args!=='object')throw Error(tr('参数必须是 JSON 对象','Arguments must be a JSON object'));pendingMCP={id:edaID,tool:edaTool,arguments:args};modal(tr('确认工具调用','Review tool call'),'<p>'+esc(edaConnections().find(function(c){return c.id===edaID}).name)+' · '+esc(edaTool)+'</p><pre>'+esc(json(args))+'</pre><p class="sub">'+tr('确认后将按当前用户权限执行所选工具。','The selected tool will execute with the current user permissions.')+'</p>'+button('confirm-mcp',tr('执行调用','Execute'),'primary'),'');break;
 case 'confirm-mcp':var receipt=await act('mcp-call',pendingMCP);closeModal();await refresh();renderEDA();toast(tr('已提交 MCP 调用：','MCP call queued: ')+receipt.id);break;
 case 'eda-guide':edaGuide();break;
 case 'cadence-config':modal(tr('Cadence 工程接入配置','Cadence project configuration'),arr(S.projects).map(function(p){return '<div class="card"><h3>'+esc(p.name)+'</h3><p class="path">ID: '+esc(p.id)+'</p><input id="cadence-'+p.id+'" class="full" placeholder="/project/cadence.json" value="'+esc(p.cadenceConfig)+'"><label>'+tr('仿真环境','Simulation environment')+'</label><select id="cadence-env-'+p.id+'">'+option('','—',p.environment)+arr(S.environments).map(function(e){return option(e.id,e.name+' '+e.version,p.environment)}).join('')+'</select>'+button('save-cadence',tr('保存该工程配置','Save configuration'),'small','data-id="'+p.id+'"')+'</div>'}).join('')||empty(tr('请先在项目与文件登记工程目录','Register a project directory first')),'');break;
 case 'save-cadence':var p=JSON.parse(JSON.stringify(S.projects.find(function(p){return p.id===el.dataset.id})));p.cadenceConfig=value('cadence-'+p.id);p.environment=value('cadence-env-'+p.id);await act('save-project',p);await refresh();toast(tr('已保存','Saved'));break;
 default:return false;
 }return true;}
