function sampleWave(){var s='time_s,vin_V,vout_V\n';for(var i=0;i<=600;i++){var t=i*1e-8,v=Math.sin(2*Math.PI*1e6*t),out=.3*Math.sin(2*Math.PI*1e6*t-.9)*(1-Math.exp(-t/5e-7));s+=t+','+v+','+out+'\n'}return s}
